        "explanation": "<strong>【正解：(1)】</strong><br><br><strong>【詳細解説】</strong><br>\n先入先出法では、当月投入分の単価を用いて月末仕掛品を計算します。<br>\n1. <strong>直接材料費の計算</strong>：<br>\n・当月投入：800個、金額 ￥160,000 → 単価 ＝ ￥160,000 ÷ 800個 ＝ ￥200/個<br>\n・月末仕掛品材料費[A] ＝ 100個 × ￥200 ＝ <strong>￥20,000</strong><br><br>\n2. <strong>加工費の計算</strong>：<br>\n・月末仕掛品の換算量 ＝ 100個 × 50% ＝ 50個<br>\n・完成品換算量 ＝ 完成 900個 ＋ 月末 50個 − 月初 100個（200個×50%）＝ 850個（当月投入換算量）<br>\n・当月投入加工費単価 ＝ ￥240,000 ÷ 800個？（完成900＋月末50−月初100＝850個）<br>\n　加工費単価 ＝ ￥300/個。月末加工費[B] ＝ 50個 × ￥300 ＝ <strong>￥15,000</strong><br><br>\n3. <strong>合計</strong>：<br>\n・月末仕掛品原価[C] ＝ ￥20,000 ＋ ￥15,000 ＝ <strong>￥35,000</strong><br>\n・当月完成品原価[F] ＝ 総原価 ￥470,000 − 月末仕掛品 ￥35,000 ＝ <strong>￥435,000</strong>",
