        "explanation": "<strong>【正解：(1)】</strong><br><br><strong>【詳細解説】</strong><br>\n固定製造原価は余剰能力の範囲内であるため増減せず、埋没原価（無関連原価）となります。<br>\n1個あたりの差額収益 ＝ ￥1,400<br>\n1個あたりの差額費用 ＝ 変動製造原価 ￥1,000 ＋ 特別梱包費 ￥100 ＝ ￥1,100<br>\n1個あたり貢献利益 ＝ ￥1,400 − ￥1,100 ＝ ￥300<br>\n増分営業利益 ＝ 300個 × ￥300 ＝ <strong>￥90,000 の利益増加</strong> となるため、注文を引き受けるのが有利です。",
